contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 firstBetLimit, uint256 secondBetLimit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (firstBetLimit) + (secondBetLimit)); require(firstBetLimit <= 1000000000000000000000000000000); require(secondBetLimit <= 1000000000000000000000000000000);
        require(firstBetLimit > 0, "firstBetLimit must be positive");
        require(secondBetLimit > 0, "secondBetLimit must be positive");
        require(secondBetLimit != firstBetLimit, "bet limits must differ");
        require(address(this).balance >= firstBetLimit + secondBetLimit, "insufficient funds");

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(firstBetLimit); if (__ESBMC_reverted()) return;

        c.wager{value: firstBetLimit}(); if (__ESBMC_reverted()) return;
        require(c.hasPlayerWagered(address(this)), "first wager must succeed");
        uint256 balanceAfterFirst = address(c).balance;

        c.AdjustBetAmounts(secondBetLimit); if (__ESBMC_reverted()) return;

        bool reverted;
        c.wager{value: secondBetLimit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balanceAfterSecond = address(c).balance;

        assert(reverted || balanceAfterSecond == balanceAfterFirst + secondBetLimit);
    }

    receive() external payable {}
}

