pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 firstBetLimit, uint256 secondBetLimit) internal {
        firstBetLimit = bound(firstBetLimit, 0, 1000000000000000000000000000000);
        secondBetLimit = bound(secondBetLimit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(firstBetLimit > 0);
        vm.assume(secondBetLimit > 0);
        vm.assume(secondBetLimit != firstBetLimit);
        vm.assume(address(this).balance >= firstBetLimit + secondBetLimit);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(firstBetLimit) {} catch { return; }
        try c.wager{value: firstBetLimit}() {} catch { return; }
        vm.assume(c.hasPlayerWagered(address(this)));
        uint256 balanceAfterFirst = address(c).balance;
        try c.AdjustBetAmounts(secondBetLimit) {} catch { return; }
        bool reverted;
        try c.wager{value: secondBetLimit}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfterSecond = address(c).balance;
        assertTrue(reverted || balanceAfterSecond == balanceAfterFirst + secondBetLimit);
    }

    function testFuzz_run(uint256 firstBetLimit, uint256 secondBetLimit) public {
        _run(firstBetLimit, secondBetLimit);
    }

    receive() external payable {}
}
